function nextMiningTierTarget(score: number, maxScore: number): string {
  const thresholds = [
    ['D', 0.2],
    ['C', 0.35],
    ['B', 0.5],
    ['A', 0.65],
    ['S', 0.8],
  ] as const;
  const next = thresholds.find(
    ([, ratio]) => score < Math.ceil(maxScore * ratio),
  );
  return next
    ? `距离 ${next[0]} 档还差 ${Math.max(0, Math.ceil(maxScore * next[1]) - score)} 分`
    : '已经达到最高档';
}

interface NativeTypewriterState {
  text: string;
  startedAt: number;
  speed: number;
  startDelay: number;
}

function asRecord(value: unknown): Record<string, unknown> | null {
  return value && typeof value === 'object'
    ? (value as Record<string, unknown>)
    : null;
}

function stringValue(
  record: Record<string, unknown> | null,
  ...keys: string[]
): string {
  if (!record) return '';
  for (const key of keys) {
    const value = record[key];
    if (typeof value === 'string' && value.trim()) return value.trim();
    if (typeof value === 'number' && Number.isFinite(value))
      return String(value);
  }
  return '';
}

function numberValue(
  record: Record<string, unknown> | null,
  ...keys: string[]
): number {
  if (!record) return 0;
  for (const key of keys) {
    const value = record[key];
    if (typeof value === 'number' && Number.isFinite(value)) return value;
    if (typeof value === 'string' && value.trim()) {
      const parsed = Number(value);
      if (Number.isFinite(parsed)) return parsed;
    }
  }
  return 0;
}

function worldChatRealmFields(message: unknown): {
  realm: string;
  stage: string;
} {
  const record = asRecord(message);
  return {
    realm: stringValue(record, 'senderRealm', 'sender_realm'),
    stage: stringValue(record, 'senderRealmStage', 'sender_realm_stage'),
  };
}

function worldChatRealmBadge(message: unknown): string {
  const { realm, stage } = worldChatRealmFields(message);
  if (realm && stage) return `「${realm}」${stage}`;
  if (realm) return `「${realm}」`;
  return stage;
}

function compact(value: string, limit: number): string {
  const normalized = value.replace(/\s+/g, ' ').trim();
  const chars = Array.from(normalized);
  return chars.length <= limit
    ? normalized
    : `${chars.slice(0, Math.max(1, limit - 1)).join('')}…`;
}

function firstArray(value: unknown): unknown[] {
  if (Array.isArray(value)) return value;
  const record = asRecord(value);
  if (!record) return [];
  for (const key of [
    'data',
    'items',
    'tasks',
    'friends',
    'mails',
    'messages',
    'rankings',
    'listings',
    'results',
    'records',
    'members',
    'invitations',
    'facilities',
    'methods',
    'paths',
    'formulas',
    'products',
    'entries',
    'history',
    'activities',
    'ranking',
    'shop',
  ]) {
    const child = record[key];
    if (Array.isArray(child)) return child;
    const nested = asRecord(child);
    if (nested) {
      const found = firstArray(nested);
      if (found.length) return found;
    }
  }
  return [];
}

function resourceData(root: unknown, key: string): unknown {
  const data = asRecord(asRecord(root)?.data);
  const resources = asRecord(data?.resources);
  return asRecord(resources?.[key])?.data;
}

function errorText(error: unknown): string {
  return error instanceof Error ? error.message : '未知错误';
}

function formatChatRelativeTime(isoString: string): string {
  const time = new Date(isoString).getTime();
  if (Number.isNaN(time)) return '刚刚';
  const diffSeconds = Math.floor((Date.now() - time) / 1000);
  if (diffSeconds < 60) return '刚刚';
  if (diffSeconds < 3600) return `${Math.floor(diffSeconds / 60)}分钟前`;
  if (diffSeconds < 86400) return `${Math.floor(diffSeconds / 3600)}小时前`;
  return `${Math.floor(diffSeconds / 86400)}天前`;
}

function requestId(): string {
  const hex = 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx';
  return hex.replace(/[xy]/g, (token) => {
    const value = Math.floor(Math.random() * 16);
    return (token === 'x' ? value : (value & 0x3) | 0x8).toString(16);
  });
}

function findBattleResult(
  value: unknown,
  depth = 0,
): Record<string, unknown> | null {
  if (depth > 6) return null;
  const record = asRecord(value);
  if (!record) return null;
  if (record.participants && record.outcome && Array.isArray(record.sequences))
    return record;
  for (const child of Object.values(record)) {
    const found = findBattleResult(child, depth + 1);
    if (found) return found;
  }
  return null;
}

function findNextTutorialTaskRecord(
  tasks: Array<Record<string, unknown>>,
): Record<string, unknown> | null {
  const tutorialByDefinition = new Map(
    tasks
      .filter((task) => stringValue(task, 'category') === 'tutorial')
      .map((task) => [stringValue(task, 'definitionId'), task] as const),
  );
  for (const definitionId of TUTORIAL_TASK_ORDER) {
    const task = tutorialByDefinition.get(definitionId);
    if (!task) return null;
    const snapshot = asRecord(task.snapshot);
    const metadata = asRecord(task.metadata);
    if (
      !snapshot?.isCompleted ||
      !hasClaimedTutorialReward({
        snapshot: snapshot ?? undefined,
        metadata: metadata ?? undefined,
      })
    ) {
      return task;
    }
  }
  return null;
}

function taskRewardSummaryLines(task: Record<string, unknown>): string[] {
  const snapshot = asRecord(task.snapshot);
  const metadata = asRecord(task.metadata);
  const summary = snapshot?.rewardSummary ?? metadata?.rewardSummary;
  return Array.isArray(summary)
    ? summary
        .map((entry) => (typeof entry === 'string' ? entry.trim() : ''))
        .filter(Boolean)
    : [];
}

function findCurrentMajorBreakthroughTaskRecord(
  cultivator: Record<string, unknown> | null | undefined,
  tasks: Array<Record<string, unknown>>,
): Record<string, unknown> | null {
  if (!cultivator) return null;
  const realmStage = stringValue(cultivator, 'realm_stage', 'realmStage');
  if (realmStage !== '圆满') return null;
  const realm = stringValue(cultivator, 'realm') as RealmType;
  const toRealm = getNextMajorRealm(realm);
  if (!toRealm) return null;
  return (
    tasks.find((task) => {
      if (stringValue(task, 'category') !== 'breakthrough_major') return false;
      const metadata = asRecord(task.metadata);
      return (
        stringValue(metadata, 'fromRealm') === realm &&
        stringValue(metadata, 'toRealm') === toRealm
      );
    }) ?? null
  );
}

function stripSceneTitleBrackets(title: string): string {
  return title
    .replace(/^(?:【|「|\[)+/, '')
    .replace(/[】」\]]+$/, '')
    .trim();
}

function formatSceneSectionTitle(title: string): string {
  return `「${stripSceneTitleBrackets(title)}」`;
}

function formatSceneFrameTitle(title: string): string {
  return `【${stripSceneTitleBrackets(title)}】`;
}

function drawMeritStamp(
  ctx: CanvasRenderingContext2D,
  tier: SponsorshipTierId,
  x: number,
  y: number,
  size: number,
): void {
  (
    globalThis as typeof globalThis & {
      __daoyouMeritStamps?: {
        draw(
          ctx: CanvasRenderingContext2D,
          tier: SponsorshipTierId,
          x: number,
          y: number,
          size: number,
        ): void;
        fetchPublic(api: {
          get(path: string): Promise<unknown>;
        }): Promise<unknown>;
      };
    }
  ).__daoyouMeritStamps?.draw(ctx, tier, x, y, size);
}

function arenaRuntime() {
  return (
    globalThis as typeof globalThis & {
      __daoyouArenaRuntime: {
        drawEntrance(
          host: unknown,
          left: number,
          width: number,
          y: number,
          hasRoom: boolean,
        ): number;
        drawTeams(
          host: unknown,
          left: number,
          width: number,
          y: number,
          alpha: Record<string, unknown>[],
          beta: Record<string, unknown>[],
        ): number;
        drawBetHeader(
          host: unknown,
          left: number,
          width: number,
          y: number,
          options: Record<string, unknown>,
        ): number;
        drawBetCard(
          host: unknown,
          left: number,
          width: number,
          y: number,
          options: Record<string, unknown>,
        ): number;
      };
    }
  ).__daoyouArenaRuntime;
}

function formatMarketCountdown(nextRefresh: number): string {
  const diff = Math.max(0, nextRefresh - Date.now());
  if (diff <= 0) return '即将刷新';
  const seconds = Math.ceil(diff / 1000);
  if (seconds < 60) return `${seconds} 秒`;
  const minutes = Math.floor(seconds / 60);
  const rem = seconds % 60;
  return rem ? `${minutes} 分 ${rem} 秒` : `${minutes} 分`;
}

function normalizeBlackMarketOverview(
  raw: unknown,
): Record<string, unknown> | null {
  const root = asRecord(raw);
  if (!root) return null;
  const payload = asRecord(root.data) ?? root;
  if (!payload) return null;
  if (typeof payload.error === 'string' && !Array.isArray(payload.npcs))
    return null;
  return payload;
}

